from AlgorithmImports import *


class ExactStrategySystem(QCAlgorithm):
    RSI_THRESHOLD = 70.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        previous_spy_close = self.spy_previous_close
        previous_spy_sma = self.spy_previous_sma

        if spy_bar is not None:
            if self.spy_sma.IsReady:
                self.spy_previous_sma = float(self.spy_sma.Current.Value)
            self.spy_previous_close = float(spy_bar.Close)

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or previous_spy_close is None
            or previous_spy_sma is None
        ):
            return

        spy_close = float(spy_bar.Close)
        spy_sma = float(self.spy_sma.Current.Value)
        aapl_rsi = float(self.aapl_rsi.Current.Value)

        strategy_a_buy = (
            previous_spy_close <= previous_spy_sma
            and spy_close > spy_sma
        )

        strategy_a_sell = (
            previous_spy_close >= previous_spy_sma
            and spy_close < spy_sma
        )

        strategy_b_buy = self.aapl_red_streak >= 3
        strategy_b_sell = aapl_rsi > self.RSI_THRESHOLD

        if (
            self.strategy_a_lot > 0
            and "A" not in self.pending_orders
            and strategy_a_sell
        ):
            self._submit_order("A", self.spy, -self.strategy_a_lot, "A|sell")

        if (
            self.strategy_b_lot > 0
            and "B" not in self.pending_orders
            and strategy_b_sell
        ):
            self._submit_order("B", self.aapl, -self.strategy_b_lot, "B|sell")

        if (
            self.strategy_a_lot == 0
            and "A" not in self.pending_orders
            and strategy_a_buy
        ):
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue))
                / spy_close
            )
            if quantity > 0:
                self._submit_order("A", self.spy, quantity, "A|buy")

        if (
            self.strategy_b_lot == 0
            and "B" not in self.pending_orders
            and strategy_b_buy
            and float(self.Portfolio.Cash) >= 20000.0
        ):
            quantity = int(20000.0 / float(aapl_bar.Close))
            if quantity > 0:
                self._submit_order("B", self.aapl, quantity, "B|buy")

    def _submit_order(self, strategy, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag)

        if ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[strategy] = ticket.OrderId

    def OnOrderEvent(self, order_event):
        if order_event.FillQuantity == 0:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag.startswith("A|"):
            self.strategy_a_lot += int(order_event.FillQuantity)
            if self.strategy_a_lot < 0:
                self.strategy_a_lot = 0
            strategy = "A"

        elif order.Tag.startswith("B|"):
            self.strategy_b_lot += int(order_event.FillQuantity)
            if self.strategy_b_lot < 0:
                self.strategy_b_lot = 0
            strategy = "B"

        else:
            return

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if self.pending_orders.get(strategy) == order_event.OrderId:
                del self.pending_orders[strategy]
